'use strict';
(function(root){
const C=root.Valley||(typeof require==='function'?require('./world-core.js'):null);
function normalize(s){s.vegetables??=0;s.cookedVegetables??=0;s.ore??=0;const removed=s.buildings.filter(b=>['garden','pen','mill'].includes(b.type));s.buildings=s.buildings.filter(b=>!['garden','pen','mill'].includes(b.type));for(let b of removed){s.wood+=b.type==='garden'?20:b.type==='pen'?35:60;s.stone+=b.type==='garden'?5:b.type==='pen'?10:30;if(b.type==='pen')for(let i=0;i<(b.flock||0);i++){let x=b.x,y=b.y;for(let yy=b.y-1;yy<=b.y+2;yy++)for(let xx=b.x-1;xx<=b.x+2;xx++)if(C.walkable(s,xx,yy)){x=xx;y=yy}s.sheep.push({id:'s'+(900000+s.sheep.length),x,y,homeX:x,homeY:y,hp:2,respawn:0})}}s.sheep=s.sheep.filter(a=>!a.domesticated);for(let a of s.sheep){delete a.penTarget;delete a.penRoute;delete a.penRetry}for(let w of s.workers||[])if(w.role==='farm'){w.role='idle';w.target=null;w.route=[];w.work=0;w.status='Отдыхает'}for(let l of s.landmarks||[])if(l.kind==='mill'&&(l.restored||l.restoreEnd)){s.wood+=60;s.stone+=30}s.landmarks??=[['cache','Забытый тайник',26,14],['ore','Рудная жила',30,31]].map(([kind,name,x,y])=>{for(let dy=0;dy<5;dy++)for(let dx=0;dx<5;dx++){let xx=x+dx,yy=y+dy;if(C.walkable(s,xx,yy))return {id:'landmark-'+kind,kind,name,x:xx,y:yy}}return {id:'landmark-'+kind,kind,name,x,y}});s.landmarks=s.landmarks.filter(l=>l.kind!=='mill');return s}
const originalNew=C.newGame;C.newGame=()=>normalize(originalNew());
const originalPlacement=C.placement;C.placement=(s,type,x,y)=>{let r=C.recipes[type];if(r&&(s.landmarks||[]).some(l=>l.x>=x&&l.x<x+r.w&&l.y>=y&&l.y<y+r.h))return 'Здесь находится памятное место';return originalPlacement(s,type,x,y)};
// startBuild in the core uses its own placement function; validate the extension first.
const originalBuild=C.startBuild;C.startBuild=(s,type,x,y)=>{let error=C.placement(s,type,x,y);return error?{error}:originalBuild(s,type,x,y)};
function discover(s,id){let l=s.landmarks.find(l=>l.id===id);if(!l)return {error:'Место не найдено'};if(Math.hypot(s.player.x-l.x-.5,s.player.y-l.y-.5)>2)return {error:'Подойдите к находке'};if(l.kind==='cache'){if(l.claimed)return {error:'Тайник уже пуст'};l.claimed=true;s.berries+=12;s.cookedFish+=4;return {message:'В тайнике: 12 порций ягод и 4 порции готовой рыбы!',sound:'complete'}}if(l.charges===0)return {error:'Жила исчерпана'};if(C.level(s)<2)return {error:'Для добычи руды сначала постройте мастерскую'};if(s.energy<8)return {error:'Для добычи нужно 8 сил'};l.charges??=5;l.charges--;s.energy-=8;s.ore+=2;return {message:'Добыто 2 руды. В мастерской из неё можно улучшить удочку.',sound:'rock'}}
function improveRod(s){if(!s.rod||C.level(s)<2)return {error:'Нужны удочка и готовая мастерская'};if(s.rodLevel===2)return {error:'Удочка уже улучшена'};if(s.ore<6||s.wood<15)return {error:'Нужно 6 руды и 15 дерева'};s.ore-=6;s.wood-=15;s.rodLevel=2;return {message:'Прочная удочка: рыбалка занимает 6 секунд вместо 9.',sound:'complete'}}
function tick(s){normalize(s);return []}
const api={normalize,tick,discover,improveRod};root.Economy=api;if(typeof module!=="undefined")module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
